-- ============================================================
--  الخطة التشغيلية 2026م — من ملف «محفظة المساهمات» 09/09/2026
--  ------------------------------------------------------------
--  مصدر هذه القيم ملفُ العرض نفسه، مقروءاً حرفياً لا منقولاً عن
--  صورة — فأسماء البنود والرعاة والمسؤولين والتواريخ وحالة كل
--  مساهمة كما وردت فيه تماماً.
--
--  **لا تُمَسّ أرقام الأرباع**: الحفظ بـ `data || ...` فلا يُكتب
--  إلا ما هنا، وتبقى `q1t..q4a` و`yearTarget` و`level` و`unit`
--  كما هي — فهي ليست في هذا الملف.
--
--  وتنتقل بنودٌ إلى محافظها الصحيحة: «دراسة الإجراءات والتقاطعات»
--  و«تقييم أساسيات الممارسات» و«لوحة بيانات المؤشرات» إلى بدر
--  الغنام، و«تجربة المستفيد» و«معايير الاجتماعات» و«الاجتماعات
--  المنعقدة» إلى عمر العتيق، و«تقويم أعمال القياس» و«انضمام
--  الموظفين الجدد» إلى دعاء الفهمي — كانت في محفظة الحزامي تخميناً.
--
--  idempotent — يُعاد تشغيله كلما تحدّث الملف أسبوعياً
-- ============================================================

update public.perf_items as t set data = t.data || v.patch
  from (values
    ('op-i06', '{"name": "إعادة النظر في عمليات دورة القياس لعام 2026م", "owner": "عبدالله الحزامي", "sponsor": "عبدالله الحزامي", "assignee": "الفريق المركزي · فريق المشروع الاستشاري", "start": "3 مايو 2026م", "end": "30 يونيو 2026م", "note": "مكتملة", "status": "مكتملة"}'::jsonb),
    ('op-i07', '{"name": "رفع الفهم والارتباط بأعمال الأجهزة العامة لمنسوبي إدارة عمليات الأداء", "owner": "عبدالله الحزامي", "sponsor": "عبدالله الحزامي", "assignee": "مدراء القطاعات", "start": "3 مايو 2026م", "end": "31 ديسمبر 2026م", "note": "العمل مستمر مع مدراء القطاعات لرفع الفهم والارتباط بأعمال الأجهزة العامة وتم الانتهاء من عمل ال cheat sheet"}'::jsonb),
    ('op-i13', '{"name": "رفع الوعي بإدارة عمليات الأداء ومهامها في المركز داخليًا لعام 2026م", "owner": "عبدالله الحزامي", "sponsor": "رؤى الحماد", "assignee": "فارس السحيباني · سلطانة العرجاني", "start": "17 مايو 2026م", "end": "31 ديسمبر 2026م", "note": "تم اعداد خطة تنفيذية لورش رفع الوعي والية تنفيذها"}'::jsonb),
    ('op-k12', '{"name": "نسبة الالتزام باتفاقيات مستوى الخدمة لمراجعة طلبات التغيير", "owner": "عبدالله الحزامي", "sponsor": "عبدالله الحزامي", "assignee": "حمد العويس · عبدالرحمن الرميح", "start": "1 يناير 2026م", "end": "31 ديسمبر 2026م", "note": "تم تسليم مسؤولية التحديث اليومي للزميلة نورا النصار كعمل تشغيلي"}'::jsonb),
