    ('op-k17', '{"name": "نسبة اتمام الخطة الفردية للاحتياج التطويري", "owner": "عبدالله الحزامي", "sponsor": "عبدالله الحزامي", "assignee": "مشاعل الدايل", "start": "1 يناير 2026م", "end": "31 ديسمبر 2026م", "note": "تم الانتهاء من اعداد الخطط الفردية لجميع الموظفين وجاري العمل على استكمالها"}'::jsonb),
