    ('op-w10', '{"name": "إنشاء لوحة بيانات للمؤشرات الداخلية لإدارة عمليات الأداء", "owner": "بدر الغنام", "sponsor": "لمى المبدل", "assignee": "سلطانة العرجاني", "start": "20 مايو 2026م", "end": "31 يوليو 2026م", "note": "تم الانتهاء من تطوير لوحة بيانات المؤشرات، ومشاركة رابط الوصول إليها مع الأستاذ/ عبدالله الحزامي"}'::jsonb),
