    ('op-i02', '{"name": "تنفيذ عمليات قياس تجربة المستفيد (الحج والعمرة) لعام 2026", "owner": "عمر العتيق", "sponsor": "ثامر الضبيب", "assignee": "خالد الجرف · ياسر بخاري · خالد الخثلان · عبدالعزيز العون", "start": "1 يناير 2026م", "end": "30 نوفمبر 2026م", "note": "-"}'::jsonb),
