    ('op-w02', '{"name": "تحديث قوالب العروض التقديمية ومحاضر الاجتماعات", "owner": "عمر العتيق", "sponsor": "لمى المبدل", "assignee": "سلطانة العرجاني · ندى العمير", "start": "13 مايو 2026م", "end": "11 يوليو 2026م", "note": "تم الانتهاء بنسبة 70% ومن المخطط الانتهاء 15 أغسطس"}'::jsonb),
