  ) as v(id, patch)
 where t.section = 'opplan' and t.id = v.id;

-- التحقق: 35 بنداً تحمل تاريخ بداية وحالة مساهمة
select count(*) filter (where data ? 'start')            as "فيها تاريخ بداية",
       count(*) filter (where coalesce(data->>'note','') <> '') as "فيها حالة مساهمة",
       count(*)                                          as "إجمالي بنود الخطة"
  from public.perf_items where section = 'opplan';

-- توزيع البنود على المحافظ بعد التصحيح
select data->>'owner' as "المحفظة",
       count(*) filter (where data->>'kind' = 'init') as "مبادرات",
       count(*) filter (where data->>'kind' = 'win')  as "مكاسب سريعة",
       count(*) filter (where data->>'kind' = 'kpi')  as "مؤشرات",
       count(*) as "الإجمالي"
  from public.perf_items where section = 'opplan'
 group by 1 order by 5 desc;
